<?php namespace App\Http\Controllers; use App\Models\{Desa,TahunAnggaran,Pendapatan,Belanja,Pembiayaan,DokumenPublikasi}; use App\Services\ApbdesaSummary;
class PublicController extends Controller { private function ctx(?int $tahun=null):array { $years=TahunAnggaran::orderBy('tahun')->get(); $year=$tahun? $years->firstWhere('tahun',$tahun):$years->firstWhere('status','aktif'); abort_unless($year,404); return compact('years','year')+['desa'=>Desa::first()]; } public function home(ApbdesaSummary $s){$c=$this->ctx(); return view('public.home',$c+['summary'=>$s->for($c['year'])]);} public function apbdesa(int $tahun,ApbdesaSummary $s){$c=$this->ctx($tahun);return view('public.apbdesa',$c+['summary'=>$s->for($c['year']),'pendapatan'=>Pendapatan::publik()->where('tahun_anggaran_id',$c['year']->id)->orderBy('urutan')->get(),'belanja'=>Belanja::publik()->with('bidang')->where('tahun_anggaran_id',$c['year']->id)->orderBy('urutan')->get(),'pembiayaan'=>Pembiayaan::publik()->where('tahun_anggaran_id',$c['year']->id)->orderBy('urutan')->get()]);} public function realisasi(int $tahun,ApbdesaSummary $s){$c=$this->ctx($tahun);return view('public.realisasi',$c+['summary'=>$s->for($c['year']),'pendapatan'=>Pendapatan::publik()->withSum(['realisasi'=>fn($q)=>$q->where('status_publikasi','dipublikasikan')],'nilai')->where('tahun_anggaran_id',$c['year']->id)->get(),'belanja'=>Belanja::publik()->with('bidang')->withSum(['realisasi'=>fn($q)=>$q->where('status_publikasi','dipublikasikan')],'nilai')->where('tahun_anggaran_id',$c['year']->id)->get()]);} public function documents(int $tahun){$c=$this->ctx($tahun);return view('public.documents',$c+['documents'=>DokumenPublikasi::where('tahun_anggaran_id',$c['year']->id)->where('status_publikasi','dipublikasikan')->latest('tanggal_publikasi')->get()]);} public function profile(){return view('public.profile',$this->ctx());}}
